type Contact = { id:string; account_id:string; first_name:string; last_name:string|null; full_name:string|null; job_title:string|null; contact_role:string|null; decision_role:string|null; email:string|null; mobile:string|null; phone:string|null; whatsapp:string|null; is_primary:boolean; is_active:boolean; custom_fields:Record<string,unknown>|null };
type PaymentSummary = { id:string; payment_no:string; currency:string; unallocated_amount:number; status:string; received_date:string|null };
type Account = { id:string; account_number:string|null; account_name:string; legal_name:string|null; account_type:string; status:string; industry:string|null; website:string|null; email:string|null; phone:string|null; fax:string|null; country_code:string|null; region:string|null; city:string|null; street:string|null; postal_code:string|null; registration_number:string|null; tax_number:string|null; vat_number:string|null; currency_code:string; payment_terms:string|null; incoterms_code:string|null; credit_limit:number|null; credit_days:number|null; source_lead_id:string|null; notes:string|null; custom_fields:Record<string,any>|null; created_at:string; updated_at:string; parent_account_id:string|null; company_type:string|null; language_code:string|null; timezone:string|null; sales_region:string|null; sales_team:string|null; account_manager:string|null; payment_method:string|null; tax_exemption_code:string|null; tax_classification:string|null; credit_status:string|null; price_list:string|null; delivery_method:string|null; shipping_terms:string|null; invoice_email:string|null; is_archived:boolean; tags:string[]; bank_name?:string|null; bank_account?:string|null };
type Address = { id:string; type:string; name:string; country:string; state:string; city:string; street:string; postalCode:string; contactId:string; phone:string; port:string; isDefault:boolean; active:boolean };
type Bank = { id:string; bankName:string; account:string; swift:string; currency:string; isDefault:boolean };
const blankAddress=():Address=>({id:crypto.randomUUID(),type:'registered',name:'',country:'',state:'',city:'',street:'',postalCode:'',contactId:'',phone:'',port:'',isDefault:true,active:true});
const blankBank=():Bank=>({id:crypto.randomUUID(),bankName:'',account:'',swift:'',currency:'USD',isDefault:false});
const countryName=(code:string)=>{if(!code)return '未设置';try{return new Intl.DisplayNames(['zh-TW'],{type:'region'}).of(code.toUpperCase())||code}catch{return code}};
const text=(v:unknown)=>typeof v==='string'?v:'';
const customerStatus=(r:Account)=>text(r.custom_fields?.customerStatus)||({active:'active',inactive:'dormant',blocked:'blacklist',unqualified:'lost',qualified:'active'} as Record<string,string>)[r.status]||'active';
const statusDb=(v:string)=>({active:'active',dormant:'inactive',lost:'unqualified',blacklist:'blocked'} as Record<string,string>)[v]||'active';
const f=(label:string,el:ReactElement)=> <div className="tp-accounts__field"><label className="tp-accounts__label" htmlFor={el.props.id}>{label}</label>{el}</div>;
const input=(id:string,label:string,value:string,onChange:(v:string)=>void,placeholder='')=><TextInput id={id} labelText={label} hideLabel value={value} placeholder={placeholder} onChange={e=>onChange(e.currentTarget.value)}/>;
const select=(id:string,label:string,value:string,onChange:(v:string)=>void,options:Array<[string,string]>)=><Select id={id} labelText={label} hideLabel value={value} onChange={e=>onChange(e.currentTarget.value)}>{options.map(([v,t])=><SelectItem key={v} value={v} text={t}/>)}</Select>;
function Metric({label,value,icon,detail}:{label:string;value:number;icon:React.ReactNode;detail:string}){return <section className="tp-accounts__metric"><div><span>{label}</span>{icon}</div><strong>{value.toLocaleString()}</strong><small>{detail}</small></section>}
function SectionTitle({icon,children}:{icon:React.ReactNode;children:React.ReactNode}){return <h2 className="tp-accounts__section-title">{icon}<span>{children}</span></h2>}
function AccountMap({rows,selectedCode,onCountrySelect}:{rows:Account[];selectedCode:string;onCountrySelect:(code:string)=>void}) {
 const data=[...rows.reduce((map,row)=>{const code=(row.country_code||'').toUpperCase();if(code&&code!=='UNKNOWN')map.set(code,(map.get(code)||0)+1);return map},new Map<string,number>())]
  .map(([code,value])=>({code,label:countryName(code),value})).sort((a,b)=>b.value-a.value);
 return <section className="tp-accounts__panel"><div className="tp-accounts__panel-head"><SectionTitle icon={<semanticIcons.globe size={20}/>}>全球客户分布</SectionTitle><p>按客户主地址国家 / 地区汇总；地图为国家级统计，不代表公司精确地址。</p></div><WorldMapChart data={data} unitLabel="家客户" selectedCode={selectedCode==='all'?undefined:selectedCode} onCountrySelect={onCountrySelect}/></section>;
}
export function AccountConsolePage(){
 const [rows,setRows]=useState<Account[]>([]);const [contacts,setContacts]=useState<Contact[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [query,setQuery]=useState('');const [status,setStatus]=useState('all');const [countryFilter,setCountryFilter]=useState('all');const [page,setPage]=useState(1);const [pageSize,setPageSize]=useState<10|20|50|100>(20);
 const load=useCallback(async()=>{setLoading(true);setError('');try{const db=await getSupabaseClient();const [a,c]=await Promise.all([db.from('crm_accounts').select('*').eq('is_archived',false).order('created_at',{ascending:false}).range(0,1999),db.from('crm_contacts').select('id,account_id,first_name,last_name,full_name,job_title,contact_role,decision_role,email,mobile,phone,whatsapp,is_primary,is_active,custom_fields').eq('is_archived',false).range(0,4999)]);if(a.error)throw a.error;if(c.error)throw c.error;setRows((a.data||[]) as Account[]);setContacts((c.data||[]) as Contact[])}catch(e){setError(e instanceof Error?e.message:'读取客户数据失败')}finally{setLoading(false)}},[]);
 useEffect(()=>{void load()},[load]);
 const filtered=useMemo(()=>rows.filter(r=>(status==='all'||customerStatus(r)===status)&&(countryFilter==='all'||String(r.country_code||'').toUpperCase()===countryFilter)&&[r.account_name,r.account_number,r.country_code,r.city,r.email,r.website,r.tax_number].join(' ').toLowerCase().includes(query.trim().toLowerCase())),[rows,status,countryFilter,query]);
 useEffect(()=>setPage(1),[query,status,countryFilter]);
 const total=rows.length,active=rows.filter(r=>r.status==='active').length,new30=rows.filter(r=>Date.now()-new Date(r.created_at).getTime()<30*86400000).length,blacklist=rows.filter(r=>customerStatus(r)==='blacklist').length;
 const industryData=useMemo(()=>{const counts=new Map<string,number>();rows.forEach(row=>{const key=row.industry||'未分类';counts.set(key,(counts.get(key)||0)+1)});return [...counts.entries()].map(([group,value])=>({group,value})).sort((a,b)=>b.value-a.value).slice(0,8)},[rows]);
 const daily=useMemo(()=>{const m=new Map<string,number>();for(let i=29;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);m.set(d.toISOString().slice(0,10),0)}rows.forEach(r=>{const k=r.created_at.slice(0,10);if(m.has(k))m.set(k,(m.get(k)||0)+1)});return [...m].map(([date,count])=>({group:'每日新增客户',date:new Date(date+'T00:00:00'),value:count}))},[rows]);
 const chartOptions={theme:document.documentElement.dataset.carbonTheme==='g100'?'g100':'white',title:'每日新增客户',axes:{bottom:{title:'日期',mapsTo:'date',scaleType:ScaleTypes.TIME},left:{title:'新增客户',mapsTo:'value',scaleType:ScaleTypes.LINEAR}},curve:'curveMonotoneX',height:'280px'};
 return <main className="tp-accounts"><PageHeader className="tp-accounts__header"><div><p className="tp-accounts__eyebrow">TRADEPILOT / CRM</p><h1>客户（Account）</h1><p>管理公司级客户资料、联系人、地址、交易与财务规则。</p></div><div className="tp-accounts__actions"><Button kind="tertiary" onClick={()=>void load()} disabled={loading}><semanticIcons.refresh size={16}/>刷新</Button><Link href="/accounts/new" renderIcon={semanticIcons.add}>新建客户</Link></div></PageHeader>
 {error&&<InlineNotification kind="error" title="客户数据读取失败" subtitle={error}/>}
 {loading?<div className="tp-accounts__loading"><InlineLoading description="正在读取客户数据…"/></div>:<>
 <div className="tp-accounts__metrics"><Metric label="全部客户" value={total} icon={<semanticIcons.building size={20}/>} detail="未归档客户总数"/><Metric label="活跃客户" value={active} icon={<semanticIcons.success size={20}/>} detail="当前活跃状态"/><Metric label="近 30 天新增" value={new30} icon={<semanticIcons.calendar size={20}/>} detail="最近 30 天创建"/><Metric label="黑名单客户" value={blacklist} icon={<semanticIcons.warning size={20}/>} detail="需谨慎开展业务"/></div>
 <section className="tp-accounts__panel"><div className="tp-accounts__panel-head"><SectionTitle icon={<semanticIcons.chart size={20}/>}>每日新增趋势</SectionTitle><p>最近 30 天客户创建数量</p></div><LineChart data={daily} options={chartOptions}/></section>
 <section className="tp-accounts__panel"><div className="tp-accounts__panel-head"><SectionTitle icon={<semanticIcons.dataVisualization size={20}/>}>客户行业结构</SectionTitle><p>按客户行业字段统计，最多展示前 8 类。</p></div>{industryData.length?<DonutChart data={industryData} options={{theme:document.documentElement.dataset.carbonTheme==='g100'?'g100':'white',height:'300px',donut:{center:{label:'客户行业'}},legend:{position:'right'},toolbar:{enabled:false}} as any}/>:<p className="tp-accounts__empty">暂无行业分类数据</p>}</section>
 <AccountMap rows={rows} selectedCode={countryFilter} onCountrySelect={code=>setCountryFilter(current=>current===code?'all':code)}/>
 <section className="tp-accounts__panel"><div className="tp-accounts__panel-head"><SectionTitle icon={<semanticIcons.building size={20}/>}>客户列表</SectionTitle><p>客户公司级主数据；人员信息在联系人对象维护。</p></div><div className="tp-accounts__filters">{f('搜索客户',input('account-search','搜索客户',query,setQuery,'名称、编号、国家、邮箱、税号'))}{f('客户状态',select('account-status','客户状态',status,setStatus,[['all','全部状态'],['active','活跃'],['dormant','休眠'],['lost','流失'],['blacklist','黑名单']]))}</div><TpDataTable
        selectable
 columns={[
  {key:'account_number',header:'客户编号',minWidth:120,render:r=>r.account_number||'—'},
  {key:'account_name',header:'客户名称',primary:true,minWidth:220,render:r=><div><Link href={'/accounts/'+r.id}>{r.account_name}</Link><small>{r.website||r.email||''}</small></div>},
  {key:'account_type',header:'类型 / 等级',minWidth:150,render:r=>(r.company_type||r.account_type||'公司')+' / '+(r.custom_fields?.grade||'未评级')},
  {key:'business_type',header:'业务类型',minWidth:130,render:r=>r.custom_fields?.businessType||'—'},
  {key:'country_code',header:'国家 / 地区',minWidth:130,render:r=>countryName(r.country_code||'')},
  {key:'primary_contact',header:'主要联系人',minWidth:160,render:r=>{const primary=contacts.find(c=>c.account_id===r.id&&c.is_primary);return primary?.full_name||[primary?.first_name,primary?.last_name].filter(Boolean).join(' ')||'未设置'}},
  {key:'status',header:'状态',minWidth:100,render:r=><Tag type={customerStatus(r)==='active'?'green':customerStatus(r)==='blacklist'?'red':'cool-gray'}>{({active:'活跃',dormant:'休眠',lost:'流失',blacklist:'黑名单'} as Record<string,string>)[customerStatus(r)]||customerStatus(r)}</Tag>},
  {key:'created_at',header:'创建时间',minWidth:130,render:r=>new Date(r.created_at).toLocaleDateString('zh-TW')},
 ]}
 rows={filtered as (Account & Record<string,unknown>)[]}
 rowKey="id"
 ariaLabel="客户列表"
 columnSettingsKey="crm-accounts"
 pagination={{page,pageSize,totalItems:filtered.length,onChange:(nextPage,nextSize)=>{setPage(nextPage);setPageSize(nextSize);}}}
/>{!filtered.length&&<p className="tp-accounts__empty">没有符合条件的客户。</p>}</section>
 </>}
 </main>
}
